DO $migration$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.process_due()'::regprocedure) INTO body; body=replace(body,'WHERE m.notified_at IS NULL AND i.status=', 'WHERE m.notified_at IS NULL AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=m.user_id AND p.match_notifications) AND i.status='); EXECUTE body; END $migration$;
CREATE OR REPLACE FUNCTION public.item_preview(item uuid) RETURNS TABLE(id uuid,title text,condition text,circle_name text,photo_path text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT i.id,i.title,i.condition,c.name,i.photo_path FROM public.items i JOIN public.circles c ON c.id=i.circle_id WHERE i.id=item AND NOT c.is_test AND i.status NOT IN('removed','donated','expired') AND (i.status<>'available' OR i.expires_at>now()) $$;
CREATE OR REPLACE FUNCTION public.invite_preview(token uuid) RETURNS TABLE(name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.name FROM public.circles c WHERE c.invite_token=token AND NOT c.is_test $$;
CREATE OR REPLACE FUNCTION public.join_from_item(item uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token uuid; cid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT c.invite_token,c.id INTO token,cid FROM public.items i JOIN public.circles c ON c.id=i.circle_id WHERE i.id=item AND NOT c.is_test AND i.status NOT IN('removed','donated','expired') AND (i.status<>'available' OR i.expires_at>now()); IF cid IS NULL THEN RAISE EXCEPTION 'This link has expired or the item was removed.'; END IF; PERFORM public.passalong_action('join',jsonb_build_object('token',token)); RETURN cid; END $$;